package com.training.accounting.auth;
import com.training.accounting.user.AppUserRepository; import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthFilter extends OncePerRequestFilter { private final JwtService js; private final AppUserRepository ur; public JwtAuthFilter(JwtService js,AppUserRepository ur){this.js=js;this.ur=ur;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){try{Claims cl=js.parse(h.substring(7)); ur.findByEmailIgnoreCase(cl.getSubject()).filter(u->u.isActive()).ifPresent(u->{var a=new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole())));a.setDetails(u);SecurityContextHolder.getContext().setAuthentication(a);});}catch(Exception ignored){}} c.doFilter(r,s);} }
